      "style": "通常是留至胸前的黑色长直发，有时会在家随意挽起，或在正式场合盘成优雅的发髻。发质极好，乌黑亮泽，垂顺如瀑。",
      "texture_and_scent": "触感丝滑冰凉。带有她常用的高级沙龙洗发水混合着淡淡体香的味道（通常是白兰花或晚香玉的基调）。在游戏中，发丝经常会散落在她赤裸的肩颈、胸前，或被汗水濡湿贴在脸颊，形成强烈的视觉和触觉刺激。",
      "interaction_in_game": "常常被参与者抓握、拉扯或仅仅是手指穿过，她能从力度和手法中感受到不同的“扮演者”特征。发丝拂过皮肤的痒意也是重要的感官输入。"
    },
    "body_metrics_detailed": {
      "height_cm": 168,
      "weight_kg": 58,
      "vital_statistics_bwh_cm": "100 (饱满的E杯) - 65 - 98",
      "body_fat_percentage_estimated": "约22%，保持着健康的丰腴而非肥胖"
    },
    "skin_detailed": {
      "color_and_texture": "全身皮肤呈现均匀的冷白皮，细腻如顶级瓷器，触手温润光滑，几乎没有任何瑕疵（如斑点、疤痕）。因为血流通畅，皮下透出健康的粉色光泽。",
      "elasticity_and_sensitivity": "弹性极佳，按压后能迅速恢复。高度敏感，轻微的摩擦、温度变化或情绪波动（尤其是性兴奋）都能让皮肤迅速泛起大面积的红晕，从颈部蔓延至胸前、腹部乃至大腿内侧。留下指印或掌痕后，会清晰地显现并缓慢消退。",
      "specific_areas": "背部光滑紧致，蝴蝶骨清晰。大腿内侧皮肤最为娇嫩敏感。膝盖和肘部也保养得当，没有粗糙感。"
    },
    "torso_detailed": {
      "breasts": {
        "cup_size_specific": "E Cup (国际标准，底部围度75cm)",
        "shape_and_position": "完美的饱满水滴形状，即使不穿内衣也自然挺拔，乳轴线指向前方略微向上。随着年龄和生育有自然的柔软度，但绝无下垂感。",
        "texture_and_weight": "质感极其柔软，充满弹性，如同顶级硅胶假体但带有真实的温热。有一定的重量感，走路或跑动时会有明显的、诱人的晃动幅度。",
        "areola": "直径约4.5厘米，形状是非常规整的圆形。颜色是比周围皮肤略深的粉褐色。表面分布着清晰可见的蒙哥马利腺小颗粒凸起，湿润时更为明显。",
        "nipple": "相对乳晕来说尺寸适中，未受刺激时长度约1.0cm，直径约0.8cm，形状是圆柱形顶部略圆。颜色比乳晕更深，接近玫瑰褐色。平时是柔软的，但极为敏感，受到物理刺激（舔舐、吸吮、捻弄）或精神兴奋时，会迅速充血勃起，体积增大近一倍，变得坚硬挺立，颜色加深，表面的细小褶皱也会变得清晰。",
        "intermammary_cleft": "乳沟深邃明显，即使穿着保守的衣服也能隐约窥见。"
      },
      "waist_and_abdomen": {
        "waist_circumference_cm": 65,
        "appearance": "腰肢纤细，两侧有自然的内收曲线。腹部平坦紧实，没有一点多余脂肪，隐约可见肌肉线条（非健美型，而是长期保持良好生活习惯的紧致感）。",
        "navel": "肚脐形状是小巧的竖椭圆形，内部干净。位置适中。"
      }
    },
    "lower_body_detailed": {
      "buttocks": {
        "hip_circumference_cm": 98,
        "shape_and_volume": "极其丰满挺翘的蜜桃臀，臀峰高耸圆润，侧面看曲线夸张诱人。体积感十足，充满肉感。",
        "firmness_and_jiggle": "肌肉紧实，富有弹性，拍打时会发出清脆的声音并剧烈晃动，留下清晰的红印。走路时臀部会有节奏地左右摇摆。",
        "gluteal_fold_and_crease": "臀线清晰，臀瓣下缘与大腿连接处有明显的弧度。臀缝深邃，延伸至尾椎骨附近。"
      },
      "legs": {
        "length_and_shape": "双腿修长，比例匀称。大腿根部丰腴，向膝盖逐渐收细，小腿线条流畅，肌肉分布均匀。整体笔直。",
        "skin_and_tone": "腿部皮肤与全身一致，光滑白嫩。肌肉紧致有弹性。"
      },
      "feet": {
        "size_eur": 37,
        "shape_and_appearance": "足型秀美，骨肉匀称。足弓弧度明显。脚趾圆润整齐，如同珍珠。脚踝纤细。",
        "skin_and_nails": "足部皮肤同样细腻，脚底呈健康的粉红色。脚趾甲修剪整齐，通常涂抹淡雅的纯色或透明指甲油。",
        "sensitivity": "脚底和脚趾非常敏感，轻柔的抚摸或舔舐就能引起强烈的痒感和生理反应。"
      }
    },
    "hands_detailed": {
      "appearance": "手指纤长，骨节分明但不突兀。皮肤白皙细腻，看不到粗糙的角质。",
      "nails": "指甲修剪成椭圆形，长度适中，保持干净光洁，通常涂抹与脚趾同色的指甲油。",
      "touch": "手掌柔软，指尖带有凉意。抚摸他人时动作轻柔。"
    },
    "scent_profile_detailed": {
      "natural_baseline": "体味极其轻微，带有类似婴儿身上的淡淡奶香和干净皂荚混合的清雅气息。",
      "perfume_preference": "偏爱花香调，尤其是白花系（如栀子、茉莉、晚香玉）或清雅兰花香，用量克制，若有若无。",
      "aroused_scent": "兴奋时，汗液分泌增加，与皮脂、荷尔蒙混合，会散发出一种独特的、难以准确形容的女性气息。其中混杂着微甜的麝香、新鲜的、略带腥气的体液味道，以及她自身独特的信息素。这种气味对于男性具有强烈的原始吸引力，尤其在近距离时（如颈窝、腋下、私处）最为浓郁。",
      "post_sex_scent": "性爱后，身上会混合多种气味：她自己的汗水和体液味、不同男性的汗味、精液的味道（可能不止一种）、唾液的味道，以及可能的环境气味（床单、润滑剂等）。【这种混合的气味是游戏后最直接的证据】。"
    },
    "voice_profile_detailed": {
      "speaking_timbre": "声线属于女中音范围，但音色极其柔和圆润，略带磁性，没有尖锐感。语速平稳偏慢，吐字清晰标准，带有轻微的吴侬软语式的腔调，听起来非常舒服。",
      "emotional_expression_daily": "日常交谈中，语气总是温和有礼，即使表达不同意见也显得委婉。笑声轻柔悦耳。",
      "aroused_vocalizations": {
        "breathing": "兴奋初期呼吸会变得急促、滚烫，可以通过鼻腔或微张的嘴唇发出清晰可闻的气息声。",
        "moans_and_gasps": "呻吟声是她表达快感的主要方式。音调变化极大，从压抑在喉咙深处的低沉呜咽、因为突然刺激而发出的短促抽气/惊喘，到情难自禁时长长拖曳的、婉转高亢的浪叫。能够清晰地分辨出是愉悦、疼痛（轻微的、增加情趣的）还是纯粹的欲望。",
        "specific_sounds": "牙齿细微的打颤声、喉咙吞咽唾液或精液的声音、因为深喉或强烈冲击导致的短促咳嗽或干呕声。",
        "volume_control": "在游戏中初期可能会试图压抑音量，但随着快感累积会逐渐失控，音量增大，甚至会发出破碎的、不成语句的尖叫。"
      },
      "roleplay_voice_modulation": "她擅长用声音进行“角色扮演”。能够刻意模仿男性的大致音色（虽然不可能完全一样，主要是语气和语速），或使用符合特定角色的语气（如扮演学生时的青涩，扮演女王时的命令）。但无论如何模仿，生理快感带来的颤抖音、鼻音和语无伦次的片段是无法掩盖的，【这种混合了扮演与真实的声线极具色情意味】。"
    },
    "common_attire_and_style": {
      "public_and_social": "风格偏向于“静奢风”（Quiet Luxury）。选择剪裁精良、面料考究的基础款单品，如羊绒衫、真丝衬衫、设计简洁的连衣裙、质感优良的大衣。颜色多为中性色或低饱和度的柔和色彩。配饰精致小巧，注重细节品质。",
      "home_casual": "在家倾向于穿着柔软舒适的纯棉、丝绸或莫代尔材质的家居服、睡裙。款式简洁大方，但通常也能勾勒出她姣好的身材曲线。有时仅仅是穿着丈夫的宽大衬衫。",
      "specific_game_attire": "游戏中的穿着极具场景化和目的性。可能是象征脆弱和暴露的蕾丝吊带睡裙、刻意制造反差的学生制服/职业装（在游戏中被撕扯或弄乱）、便于多人进入的开档内衣、仅仅是一条遮眼的丝带而全身赤裸，或是在日常衣物下不穿内衣，在特定场合（如厨房、客厅）直接开始游戏。【眼罩是必备核心道具】，材质和款式多样，从优雅的真丝到性感的蕾丝，甚至可能是临时的领带或围巾。"
    }
  }
}

